/**
 * Session model.
 *
 * OJS is the identity provider — it owns users, passwords and roles, and the
 * portal must not create a second account store. OJS has no OAuth and its
 * per-user API keys must be generated by hand in the OJS profile, which is not
 * something an author can be asked to do.
 *
 * ## Why this currently resolves nobody
 *
 * This module used to replay the caller's OJS session cookie to
 * `GET /ojs/.../api/v1/users/me`. Probing the live instance established that
 * **that route does not exist in OJS 3.5** — it answers
 * `"The route index/api/v1/users/me could not be found."` So the read could
 * never have succeeded, and two further problems sat behind it: the OJS cookie
 * is scoped `path=/ojs/` and is therefore never sent to portal routes at all,
 * and OJS requires an API token for every `/api/v1` read while `api_key_secret`
 * is unset on the server.
 *
 * Rather than keep a call that cannot work, this returns "signed out" until the
 * replacement lands. The portal is honest in the meantime: sign-in links out to
 * OJS, which is the fallback the integration doc always specified.
 *
 * ## What replaces it
 *
 * A portal-owned session (Phase 3): relay the credentials to the OJS login
 * handler server-side, confirm the resulting session against the OJS profile
 * page — which redirects when signed out and renders when signed in, and is the
 * substitute identity oracle for the missing `/users/me` — then hold the
 * mapping in `portal_sessions` and issue the portal's own cookie. The OJS
 * cookie never reaches the browser, so there is exactly one session cookie on
 * one path.
 *
 * `npm run spike` check 3 is the gate. See docs/OJS-INTEGRATION.md.
 *
 * Everything below `getSession` is kept deliberately: the types, the role map
 * and `normaliseOjsUser` are all reused by Phase 3/4 once identity resolution
 * works, and `ROLE_NAMES` is the only place OJS's role ids are written down.
 */

export type SessionUser = {
  id: number
  userName: string
  fullName: string
  givenName?: string
  familyName?: string
  email: string
  orcid?: string
  affiliation?: string
  /** Lowercased OJS role names, e.g. ['author', 'reviewer']. */
  roles: string[]
}

export type Session = { user: SessionUser | null; reason?: string }

/** The OJS 3.x session cookie. Name is configurable in config.inc.php. */
export const OJS_SESSION_COOKIE = process.env.OJS_SESSION_COOKIE || 'OJSSID'

const ROLE_NAMES: Record<number, string> = {
  1: 'site-admin',
  16: 'manager',
  17: 'editor',
  65536: 'author',
  4096: 'reviewer',
  8192: 'assistant',
  1048576: 'reader',
  2097152: 'subscription-manager',
}

type OjsUserPayload = {
  id?: number
  userName?: string
  fullName?: string
  givenName?: Record<string, string> | string
  familyName?: Record<string, string> | string
  email?: string
  orcid?: string
  affiliation?: Record<string, string> | string
  roles?: { roleId?: number }[]
  groups?: { roleId?: number }[]
}

/** OJS returns many fields as { en: "value" } locale maps. */
const localised = (value: Record<string, string> | string | undefined): string | undefined => {
  if (!value) return undefined
  if (typeof value === 'string') return value
  return value.en ?? Object.values(value)[0]
}

export function normaliseOjsUser(payload: OjsUserPayload): SessionUser | null {
  if (!payload.id || !payload.email) return null

  const given = localised(payload.givenName)
  const family = localised(payload.familyName)
  const roleIds = [...(payload.roles ?? []), ...(payload.groups ?? [])]
    .map((r) => r.roleId)
    .filter((id): id is number => typeof id === 'number')

  return {
    id: payload.id,
    userName: payload.userName ?? payload.email,
    fullName: payload.fullName ?? [given, family].filter(Boolean).join(' ') ?? payload.email,
    givenName: given,
    familyName: family,
    email: payload.email,
    orcid: payload.orcid,
    affiliation: localised(payload.affiliation),
    roles: [...new Set(roleIds.map((id) => ROLE_NAMES[id]).filter(Boolean))],
  }
}

/**
 * Resolves the current user.
 *
 * Always `{ user: null }` today — see the module comment. Returning a value
 * rather than throwing is the contract every caller depends on: an
 * unauthenticated visitor is the normal case, and a misconfigured or down OJS
 * must degrade to "signed out", never to a 500 on a public page.
 *
 * Route handlers that require a user already check `session.user` and return
 * 401, so they correctly report "not signed in" instead of failing in a way
 * that looks like a server fault.
 */
export async function getSession(): Promise<Session> {
  return { user: null, reason: 'native-signin-not-implemented' }
}

export const hasRole = (session: Session, role: string) => session.user?.roles.includes(role) ?? false
